for x in select value from jsonb_array_elements('[{"identity":"repo:https://github.com/excalidraw/excalidraw","slug":"excalidraw-d1cdf0bd","name":"Excalidraw","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Một sơ đồ vẽ tay có thể giải thích workflow tốt hơn cả đoạn mô tả dài.","description":"Excalidraw là bảng vẽ kiểu phác tay cho sơ đồ, wireframe và ý tưởng. Creator có thể dùng để giải thích quy trình tool hoặc lên bố cục nội dung mà không cần phần mềm thiết kế nặng. Cần phân biệt ứng dụng website với thư viện nhúng vào sản phẩm.","long_description":"ĐIỂM NỔI BẬT\n• Canvas vô hạn, hình khối, mũi tên có nhãn và thư viện shape.\n• Xuất PNG/SVG và file .excalidraw để sửa tiếp.\n• Website có cộng tác real-time, lưu local và mã hóa đầu cuối theo README.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nVẽ sơ đồ ý tưởng → script → voice → timestamp → dựng, rồi xuất ảnh để giới thiệu video kit.\n\nBẮT ĐẦU\nDùng editor chính chủ nếu chỉ cần vẽ; npm package dành cho người tích hợp vào app.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nKhông mặc định thư viện npm có đủ các tính năng website. File hoặc link chia sẻ vẫn cần quản lý quyền và bản sao lưu.","canonical_url":"https://github.com/excalidraw/excalidraw","repository_url":"https://github.com/excalidraw/excalidraw","documentation_url":"https://raw.githubusercontent.com/excalidraw/excalidraw/master/README.md","owner_name":"excalidraw","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":71,"categories":["design","content"],"primaryCategory":"design","selectionReason":"Phù hợp Design & Frontend: Một sơ đồ vẽ tay có thể giải thích workflow tốt hơn cả đoạn mô tả dài. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Một sơ đồ vẽ tay có thể giải thích workflow tốt hơn cả đoạn mô tả dài.","highlights":["Canvas vô hạn, hình khối, mũi tên có nhãn và thư viện shape.","Xuất PNG/SVG và file .excalidraw để sửa tiếp.","Website có cộng tác real-time, lưu local và mã hóa đầu cuối theo README."],"example":"Vẽ sơ đồ ý tưởng → script → voice → timestamp → dựng, rồi xuất ảnh để giới thiệu video kit.","setup":"Dùng editor chính chủ nếu chỉ cần vẽ; npm package dành cho người tích hợp vào app.","limitations":"Không mặc định thư viện npm có đủ các tính năng website. File hoặc link chia sẻ vẫn cần quản lý quyền và bản sao lưu.","github":{"stars":131078,"forks":15125,"observedAt":"2026-09-03T16:09:01.022Z","url":"https://github.com/excalidraw/excalidraw","pushedAt":"2026-09-03T15:24:44Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/excalidraw/excalidraw/master/README.md","observedAt":"2026-09-03T16:10:35.244Z","sha256":"011eea74cbbf38fd263ec93a221f379466c557dc7587acfe93797201193a7e7a"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"excalidraw/excalidraw:metadata","source_url":"https://github.com/excalidraw/excalidraw","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Avladmandic%2Fsdnext%20repo%3Alllyasviel%2Fstable-diffusion-webui-forge%20repo%3APaddlePaddle%2FPaddleOCR%20repo%3AUmi-OCR%2FUmi-OCR%20repo%3Apenpot%2Fpenpot%20repo%3Aexcalidraw%2Fexcalidraw%20repo%3Atldraw%2Ftldraw%20repo%3Aslidevjs%2Fslidev&per_page=100","stars":131078,"forks":15125,"license":"MIT"},"fetched_at":"2026-09-03T16:09:01.022Z"},{"source_type":"github","source_identifier":"excalidraw/excalidraw:readme:011eea74cbbf38fd263ec93a221f379466c557dc7587acfe93797201193a7e7a","source_url":"https://raw.githubusercontent.com/excalidraw/excalidraw/master/README.md","raw_metadata":{"sha256":"011eea74cbbf38fd263ec93a221f379466c557dc7587acfe93797201193a7e7a","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:35.244Z"}],"expected":null},{"identity":"repo:https://github.com/nextlevelbuilder/ui-ux-pro-max-skill","slug":"ui-ux-pro-max-255d217f","name":"UI UX Pro Max","type":"SKILL","status":"CANDIDATE","tagline":"Cho AI một bộ nguyên tắc thiết kế trước khi yêu cầu nó dựng website.","description":"UI UX Pro Max là skill hỗ trợ agent chọn định hướng giao diện, màu, typography và các kiểm tra UX theo brief. Điểm hữu ích không chỉ ở làm đẹp, mà ở việc đặt các yêu cầu về tương phản, focus và responsive vào quy trình xây trang.","long_description":"ĐIỂM NỔI BẬT\n• Design System Generator gợi ý hệ thiết kế theo nhu cầu dự án.\n• Có hướng dẫn và checklist tương tác, accessibility, responsive.\n• Có cách cài theo nhiều agent và phạm vi project/global.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nĐưa brief thương hiệu và đối tượng đọc vào trước, dùng skill để kiểm tra thiết kế landing page bán video kit.\n\nBẮT ĐẦU\nTheo hướng dẫn package hiện tại ui-ux-pro-max-cli; chọn đúng agent, không cần cài tất cả.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nGợi ý palette/layout không thay thế nhận diện đã có. Skill không tự chứng nhận accessibility; vẫn phải kiểm tra màn hình thật, bàn phím và nội dung Việt.","canonical_url":"https://github.com/nextlevelbuilder/ui-ux-pro-max-skill","repository_url":"https://github.com/nextlevelbuilder/ui-ux-pro-max-skill","documentation_url":"https://raw.githubusercontent.com/nextlevelbuilder/ui-ux-pro-max-skill/main/README.md","owner_name":"nextlevelbuilder","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":72,"categories":["design"],"primaryCategory":"design","selectionReason":"Phù hợp Design & Frontend: Cho AI một bộ nguyên tắc thiết kế trước khi yêu cầu nó dựng website. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Cho AI một bộ nguyên tắc thiết kế trước khi yêu cầu nó dựng website.","highlights":["Design System Generator gợi ý hệ thiết kế theo nhu cầu dự án.","Có hướng dẫn và checklist tương tác, accessibility, responsive.","Có cách cài theo nhiều agent và phạm vi project/global."],"example":"Đưa brief thương hiệu và đối tượng đọc vào trước, dùng skill để kiểm tra thiết kế landing page bán video kit.","setup":"Theo hướng dẫn package hiện tại ui-ux-pro-max-cli; chọn đúng agent, không cần cài tất cả.","limitations":"Gợi ý palette/layout không thay thế nhận diện đã có. Skill không tự chứng nhận accessibility; vẫn phải kiểm tra màn hình thật, bàn phím và nội dung Việt.","github":{"stars":124593,"forks":13333,"observedAt":"2026-09-03T16:09:07.643Z","url":"https://github.com/nextlevelbuilder/ui-ux-pro-max-skill","pushedAt":"2026-09-03T14:13:39Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/nextlevelbuilder/ui-ux-pro-max-skill/main/README.md","observedAt":"2026-09-03T16:10:42.350Z","sha256":"a2c3707e78aa0a0d86ec96ab35f8b606632dbd07f57c4c912ad8523129c04d87"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"nextlevelbuilder/ui-ux-pro-max-skill:metadata","source_url":"https://github.com/nextlevelbuilder/ui-ux-pro-max-skill","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Apresenton%2Fpresenton%20repo%3Amarp-team%2Fmarp%20repo%3Anextlevelbuilder%2Fui-ux-pro-max-skill%20repo%3Apbakaus%2Fimpeccable%20repo%3Aleonxlnx%2Ftaste-skill%20repo%3Ashadcn-ui%2Fui%20repo%3An8n-io%2Fn8n%20repo%3Aactivepieces%2Factivepieces&per_page=100","stars":124593,"forks":13333,"license":"MIT"},"fetched_at":"2026-09-03T16:09:07.643Z"},{"source_type":"github","source_identifier":"nextlevelbuilder/ui-ux-pro-max-skill:readme:a2c3707e78aa0a0d86ec96ab35f8b606632dbd07f57c4c912ad8523129c04d87","source_url":"https://raw.githubusercontent.com/nextlevelbuilder/ui-ux-pro-max-skill/main/README.md","raw_metadata":{"sha256":"a2c3707e78aa0a0d86ec96ab35f8b606632dbd07f57c4c912ad8523129c04d87","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:42.350Z"}],"expected":null},{"identity":"repo:https://github.com/shadcn-ui/ui","slug":"shadcn-ui-ad2be167","name":"shadcn/ui","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Bắt đầu từ thành phần giao diện có thể sửa, rồi làm thành bộ nhận diện của riêng bạn.","description":"shadcn/ui cung cấp mã các component để tùy chỉnh và xây thư viện riêng. Với creator có website, đây là nền để người dựng làm form, giao diện và tương tác thống nhất. Nó là vật liệu xây UI, không phải một bộ nhận diện hoàn chỉnh hay công cụ tạo video.","long_description":"ĐIỂM NỔI BẬT\n• Component có mã nguồn để thay đổi theo nhu cầu.\n• Có tài liệu chính chủ theo từng phần.\n• Mã được phát hành MIT và định hướng xây thư viện của riêng bạn.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nNhờ người dựng hoặc agent tạo bộ thành phần cho website, sau đó chỉnh màu, chữ và trạng thái theo thương hiệu.\n\nBẮT ĐẦU\nBắt đầu từ tài liệu cài đặt cho framework đang dùng; chỉ thêm component cần thiết.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nCần code để tích hợp. Dùng component phổ biến không bảo đảm website có cá tính; kiểm tra accessibility và cập nhật phần mã bạn đã nhận.","canonical_url":"https://github.com/shadcn-ui/ui","repository_url":"https://github.com/shadcn-ui/ui","documentation_url":"https://raw.githubusercontent.com/shadcn-ui/ui/main/README.md","owner_name":"shadcn-ui","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":73,"categories":["design"],"primaryCategory":"design","selectionReason":"Phù hợp Design & Frontend: Bắt đầu từ thành phần giao diện có thể sửa, rồi làm thành bộ nhận diện của riêng bạn. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Bắt đầu từ thành phần giao diện có thể sửa, rồi làm thành bộ nhận diện của riêng bạn.","highlights":["Component có mã nguồn để thay đổi theo nhu cầu.","Có tài liệu chính chủ theo từng phần.","Mã được phát hành MIT và định hướng xây thư viện của riêng bạn."],"example":"Nhờ người dựng hoặc agent tạo bộ thành phần cho website, sau đó chỉnh màu, chữ và trạng thái theo thương hiệu.","setup":"Bắt đầu từ tài liệu cài đặt cho framework đang dùng; chỉ thêm component cần thiết.","limitations":"Cần code để tích hợp. Dùng component phổ biến không bảo đảm website có cá tính; kiểm tra accessibility và cập nhật phần mã bạn đã nhận.","github":{"stars":122919,"forks":10086,"observedAt":"2026-09-03T16:09:07.643Z","url":"https://github.com/shadcn-ui/ui","pushedAt":"2026-09-02T16:34:12Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/shadcn-ui/ui/main/README.md","observedAt":"2026-09-03T16:10:43.732Z","sha256":"bb0869848a2063e405b141aa6fae8b10f132ac45036f613459e2d778b7609619"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"shadcn-ui/ui:metadata","source_url":"https://github.com/shadcn-ui/ui","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Apresenton%2Fpresenton%20repo%3Amarp-team%2Fmarp%20repo%3Anextlevelbuilder%2Fui-ux-pro-max-skill%20repo%3Apbakaus%2Fimpeccable%20repo%3Aleonxlnx%2Ftaste-skill%20repo%3Ashadcn-ui%2Fui%20repo%3An8n-io%2Fn8n%20repo%3Aactivepieces%2Factivepieces&per_page=100","stars":122919,"forks":10086,"license":"MIT"},"fetched_at":"2026-09-03T16:09:07.643Z"},{"source_type":"github","source_identifier":"shadcn-ui/ui:readme:bb0869848a2063e405b141aa6fae8b10f132ac45036f613459e2d778b7609619","source_url":"https://raw.githubusercontent.com/shadcn-ui/ui/main/README.md","raw_metadata":{"sha256":"bb0869848a2063e405b141aa6fae8b10f132ac45036f613459e2d778b7609619","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:43.732Z"}],"expected":null},{"identity":"repo:https://github.com/leonxlnx/taste-skill","slug":"taste-skill-dd01b9a3","name":"Taste Skill","type":"SKILL","status":"CANDIDATE","tagline":"Website do AI dựng không nhất thiết phải giống mọi landing page khác.","description":"Taste Skill tập hợp hướng dẫn cho AI về bố cục, typography, khoảng cách và chuyển động. Repo tách skill triển khai code với skill tạo ảnh tham chiếu, giúp chọn đúng đầu ra thay vì trộn cả hai. Bản mặc định v2 hiện được tác giả đánh dấu thử nghiệm.","long_description":"ĐIỂM NỔI BẬT\n• Hướng dẫn design-taste-frontend và các biến thể thiết kế.\n• Có hướng audit/redesign cho website đã có.\n• Tách bộ tạo reference web/mobile/brand khỏi bộ viết code.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nCho agent đọc brief và giao diện hiện tại, chọn một skill phù hợp để làm lại hero mà vẫn giữ nhận diện.\n\nBẮT ĐẦU\nCài đúng tên skill cần dùng hoặc đọc file tương ứng; dự án cần hành vi v1 có bản pin riêng.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nKhông cần dùng tất cả skill một lúc vì có thể mâu thuẫn phong cách. v2 còn thử nghiệm; lời hướng dẫn thiết kế phải nhường yêu cầu thương hiệu và kiểm thử thực tế.","canonical_url":"https://github.com/Leonxlnx/taste-skill","repository_url":"https://github.com/Leonxlnx/taste-skill","documentation_url":"https://raw.githubusercontent.com/Leonxlnx/taste-skill/main/README.md","owner_name":"Leonxlnx","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":74,"categories":["design"],"primaryCategory":"design","selectionReason":"Phù hợp Design & Frontend: Website do AI dựng không nhất thiết phải giống mọi landing page khác. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Website do AI dựng không nhất thiết phải giống mọi landing page khác.","highlights":["Hướng dẫn design-taste-frontend và các biến thể thiết kế.","Có hướng audit/redesign cho website đã có.","Tách bộ tạo reference web/mobile/brand khỏi bộ viết code."],"example":"Cho agent đọc brief và giao diện hiện tại, chọn một skill phù hợp để làm lại hero mà vẫn giữ nhận diện.","setup":"Cài đúng tên skill cần dùng hoặc đọc file tương ứng; dự án cần hành vi v1 có bản pin riêng.","limitations":"Không cần dùng tất cả skill một lúc vì có thể mâu thuẫn phong cách. v2 còn thử nghiệm; lời hướng dẫn thiết kế phải nhường yêu cầu thương hiệu và kiểm thử thực tế.","github":{"stars":83980,"forks":5740,"observedAt":"2026-09-03T16:09:07.643Z","url":"https://github.com/Leonxlnx/taste-skill","pushedAt":"2026-08-24T15:23:56Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/Leonxlnx/taste-skill/main/README.md","observedAt":"2026-09-03T16:10:44.093Z","sha256":"6e3c818b8c561e16a743cc68143d14dfa9f5da69f834c389f278657d60ca37be"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"Leonxlnx/taste-skill:metadata","source_url":"https://github.com/Leonxlnx/taste-skill","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Apresenton%2Fpresenton%20repo%3Amarp-team%2Fmarp%20repo%3Anextlevelbuilder%2Fui-ux-pro-max-skill%20repo%3Apbakaus%2Fimpeccable%20repo%3Aleonxlnx%2Ftaste-skill%20repo%3Ashadcn-ui%2Fui%20repo%3An8n-io%2Fn8n%20repo%3Aactivepieces%2Factivepieces&per_page=100","stars":83980,"forks":5740,"license":"MIT"},"fetched_at":"2026-09-03T16:09:07.643Z"},{"source_type":"github","source_identifier":"Leonxlnx/taste-skill:readme:6e3c818b8c561e16a743cc68143d14dfa9f5da69f834c389f278657d60ca37be","source_url":"https://raw.githubusercontent.com/Leonxlnx/taste-skill/main/README.md","raw_metadata":{"sha256":"6e3c818b8c561e16a743cc68143d14dfa9f5da69f834c389f278657d60ca37be","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:44.093Z"}],"expected":null},{"identity":"repo:https://github.com/pbakaus/impeccable","slug":"impeccable-1242de7b","name":"Impeccable","type":"SKILL","status":"CANDIDATE","tagline":"Thay yêu cầu mơ hồ “làm đẹp hơn” bằng các vòng audit, chỉnh bố cục và hoàn thiện cụ thể.","description":"Impeccable của Paul Bakaus cung cấp ngôn ngữ làm việc chung với AI coding agent về thiết kế. Nó lưu bối cảnh sản phẩm riêng với định hướng bề mặt, rồi dùng các lệnh như critique, polish, harden để cải thiện theo mục tiêu. Các quy tắc tự động chỉ là một phần của đánh giá.","long_description":"ĐIỂM NỔI BẬT\n• Init ghi bối cảnh sản phẩm, document/extract hỗ trợ hệ thiết kế.\n• Có audit, typeset, layout, adapt, animate và các vòng chỉnh khác.\n• README nêu detector xác định và khả năng lặp trực tiếp trong browser.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nRà một trang giới thiệu tool: làm rõ thứ bậc chữ, sửa tràn tiếng Việt rồi kiểm tra mobile trước khi đăng.\n\nBẮT ĐẦU\nChọn provider và phạm vi cài, đọc quyền hook nếu công cụ yêu cầu; dùng lệnh phù hợp từng lần.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nDetector không chứng minh mọi vấn đề UX đã hết. Không áp dụng các cấm/gợi ý hình thức máy móc nếu chúng trái hệ nhận diện hiện có.","canonical_url":"https://github.com/pbakaus/impeccable","repository_url":"https://github.com/pbakaus/impeccable","documentation_url":"https://raw.githubusercontent.com/pbakaus/impeccable/main/README.md","owner_name":"pbakaus","license":"Apache-2.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":75,"categories":["design"],"primaryCategory":"design","selectionReason":"Phù hợp Design & Frontend: Thay yêu cầu mơ hồ “làm đẹp hơn” bằng các vòng audit, chỉnh bố cục và hoàn thiện cụ thể. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Thay yêu cầu mơ hồ “làm đẹp hơn” bằng các vòng audit, chỉnh bố cục và hoàn thiện cụ thể.","highlights":["Init ghi bối cảnh sản phẩm, document/extract hỗ trợ hệ thiết kế.","Có audit, typeset, layout, adapt, animate và các vòng chỉnh khác.","README nêu detector xác định và khả năng lặp trực tiếp trong browser."],"example":"Rà một trang giới thiệu tool: làm rõ thứ bậc chữ, sửa tràn tiếng Việt rồi kiểm tra mobile trước khi đăng.","setup":"Chọn provider và phạm vi cài, đọc quyền hook nếu công cụ yêu cầu; dùng lệnh phù hợp từng lần.","limitations":"Detector không chứng minh mọi vấn đề UX đã hết. Không áp dụng các cấm/gợi ý hình thức máy móc nếu chúng trái hệ nhận diện hiện có.","github":{"stars":65241,"forks":4014,"observedAt":"2026-09-03T16:09:07.643Z","url":"https://github.com/pbakaus/impeccable","pushedAt":"2026-09-03T15:54:23Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/pbakaus/impeccable/main/README.md","observedAt":"2026-09-03T16:10:44.612Z","sha256":"9ed8c7a33e760ce7a43d1074fe630d957ccf9c0c56037b204ed79ac33a3ad467"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"pbakaus/impeccable:metadata","source_url":"https://github.com/pbakaus/impeccable","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Apresenton%2Fpresenton%20repo%3Amarp-team%2Fmarp%20repo%3Anextlevelbuilder%2Fui-ux-pro-max-skill%20repo%3Apbakaus%2Fimpeccable%20repo%3Aleonxlnx%2Ftaste-skill%20repo%3Ashadcn-ui%2Fui%20repo%3An8n-io%2Fn8n%20repo%3Aactivepieces%2Factivepieces&per_page=100","stars":65241,"forks":4014,"license":"Apache-2.0"},"fetched_at":"2026-09-03T16:09:07.643Z"},{"source_type":"github","source_identifier":"pbakaus/impeccable:readme:9ed8c7a33e760ce7a43d1074fe630d957ccf9c0c56037b204ed79ac33a3ad467","source_url":"https://raw.githubusercontent.com/pbakaus/impeccable/main/README.md","raw_metadata":{"sha256":"9ed8c7a33e760ce7a43d1074fe630d957ccf9c0c56037b204ed79ac33a3ad467","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:44.612Z"}],"expected":null},{"identity":"repo:https://github.com/penpot/penpot","slug":"penpot-33f4cdb4","name":"Penpot","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Thiết kế landing page và giữ màu, chữ, thành phần nhất quán trước khi đưa cho người dựng.","description":"Penpot là nền tảng thiết kế/prototype mở dùng trong trình duyệt hoặc tự triển khai. Các chuẩn SVG/CSS/HTML, design token và cộng tác giúp chuyển thiết kế sang sản phẩm có hệ thống. Phù hợp nhóm creator có website, bộ nhận diện và nhiều trang cần cùng phong cách.","long_description":"ĐIỂM NỔI BẬT\n• Design token, component và variant để tái sử dụng.\n• Flex/Grid cho bố cục gần cách web hoạt động.\n• Inspect, API/plugin và MCP phục vụ kết nối design–code.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nLàm bộ màu, chữ và mẫu card cho website nội dung, chia sẻ bản thiết kế để dựng thống nhất.\n\nBẮT ĐẦU\nChọn SaaS hoặc self-host theo hướng dẫn; bắt đầu với một file và thư viện thành phần nhỏ.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nSelf-host cần vận hành và sao lưu. MCP/API không tự bảo đảm code giống thiết kế; vẫn phải kiểm tra responsive, font và quyền chia sẻ.","canonical_url":"https://github.com/penpot/penpot","repository_url":"https://github.com/penpot/penpot","documentation_url":"https://raw.githubusercontent.com/penpot/penpot/develop/README.md","owner_name":"penpot","license":"MPL-2.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":76,"categories":["design"],"primaryCategory":"design","selectionReason":"Phù hợp Design & Frontend: Thiết kế landing page và giữ màu, chữ, thành phần nhất quán trước khi đưa cho người dựng. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Thiết kế landing page và giữ màu, chữ, thành phần nhất quán trước khi đưa cho người dựng.","highlights":["Design token, component và variant để tái sử dụng.","Flex/Grid cho bố cục gần cách web hoạt động.","Inspect, API/plugin và MCP phục vụ kết nối design–code."],"example":"Làm bộ màu, chữ và mẫu card cho website nội dung, chia sẻ bản thiết kế để dựng thống nhất.","setup":"Chọn SaaS hoặc self-host theo hướng dẫn; bắt đầu với một file và thư viện thành phần nhỏ.","limitations":"Self-host cần vận hành và sao lưu. MCP/API không tự bảo đảm code giống thiết kế; vẫn phải kiểm tra responsive, font và quyền chia sẻ.","github":{"stars":59540,"forks":4046,"observedAt":"2026-09-03T16:09:01.022Z","url":"https://github.com/penpot/penpot","pushedAt":"2026-09-03T15:52:42Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/penpot/penpot/develop/README.md","observedAt":"2026-09-03T16:10:36.751Z","sha256":"21c08b2e46c2a5febe92fce5357e2903bb61d8e0baa509e8e8b5d7ec7ff108d8"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"penpot/penpot:metadata","source_url":"https://github.com/penpot/penpot","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Avladmandic%2Fsdnext%20repo%3Alllyasviel%2Fstable-diffusion-webui-forge%20repo%3APaddlePaddle%2FPaddleOCR%20repo%3AUmi-OCR%2FUmi-OCR%20repo%3Apenpot%2Fpenpot%20repo%3Aexcalidraw%2Fexcalidraw%20repo%3Atldraw%2Ftldraw%20repo%3Aslidevjs%2Fslidev&per_page=100","stars":59540,"forks":4046,"license":"MPL-2.0"},"fetched_at":"2026-09-03T16:09:01.022Z"},{"source_type":"github","source_identifier":"penpot/penpot:readme:21c08b2e46c2a5febe92fce5357e2903bb61d8e0baa509e8e8b5d7ec7ff108d8","source_url":"https://raw.githubusercontent.com/penpot/penpot/develop/README.md","raw_metadata":{"sha256":"21c08b2e46c2a5febe92fce5357e2903bb61d8e0baa509e8e8b5d7ec7ff108d8","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:36.751Z"}],"expected":null},{"identity":"repo:https://github.com/tldraw/tldraw","slug":"tldraw-f2ca5604","name":"tldraw","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Muốn một bảng ý tưởng có thể biến thành công cụ riêng cho team? Đây là bộ nền canvas.","description":"tldraw SDK giúp xây ứng dụng canvas trong React với hình khối, vẽ, media và tương tác tùy chỉnh. Các starter kit có hướng agent, image pipeline và workflow. Đây là lựa chọn cho người muốn tạo công cụ làm nội dung riêng, không chỉ tải một app vẽ miễn phí.","long_description":"ĐIỂM NỔI BẬT\n• Canvas với rich text, mũi tên, ảnh/video và xuất ảnh.\n• Tùy chỉnh shape, tool và điều khiển canvas qua API.\n• Có starter kit cho cộng tác, agent và pipeline kéo thả.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nThử bảng storyboard có ảnh cảnh, ghi chú và trạng thái duyệt trong một prototype cho team.\n\nBẮT ĐẦU\nCần project React hoặc hỗ trợ kỹ thuật; chọn starter kit phù hợp thay vì tự dựng toàn bộ.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nSDK dùng giấy phép tldraw; production cần license key theo README. Starter kit MIT không làm SDK trở thành MIT.","canonical_url":"https://github.com/tldraw/tldraw","repository_url":"https://github.com/tldraw/tldraw","documentation_url":"https://raw.githubusercontent.com/tldraw/tldraw/main/README.md","owner_name":"tldraw","license":"tldraw SDK License: development miễn phí, production cần key; starter kit có MIT riêng.","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":77,"categories":["design","automation"],"primaryCategory":"design","selectionReason":"Phù hợp Design & Frontend: Muốn một bảng ý tưởng có thể biến thành công cụ riêng cho team? Đây là bộ nền canvas. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Muốn một bảng ý tưởng có thể biến thành công cụ riêng cho team? Đây là bộ nền canvas.","highlights":["Canvas với rich text, mũi tên, ảnh/video và xuất ảnh.","Tùy chỉnh shape, tool và điều khiển canvas qua API.","Có starter kit cho cộng tác, agent và pipeline kéo thả."],"example":"Thử bảng storyboard có ảnh cảnh, ghi chú và trạng thái duyệt trong một prototype cho team.","setup":"Cần project React hoặc hỗ trợ kỹ thuật; chọn starter kit phù hợp thay vì tự dựng toàn bộ.","limitations":"SDK dùng giấy phép tldraw; production cần license key theo README. Starter kit MIT không làm SDK trở thành MIT.","github":{"stars":50107,"forks":3493,"observedAt":"2026-09-03T16:09:01.022Z","url":"https://github.com/tldraw/tldraw","pushedAt":"2026-09-03T15:50:48Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/tldraw/tldraw/main/README.md","observedAt":"2026-09-03T16:10:37.417Z","sha256":"db3ce68f8c5f0652fe9724cfb5c64cb98898a64c4776e59e134c6e719296ea00"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"tldraw/tldraw:metadata","source_url":"https://github.com/tldraw/tldraw","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Avladmandic%2Fsdnext%20repo%3Alllyasviel%2Fstable-diffusion-webui-forge%20repo%3APaddlePaddle%2FPaddleOCR%20repo%3AUmi-OCR%2FUmi-OCR%20repo%3Apenpot%2Fpenpot%20repo%3Aexcalidraw%2Fexcalidraw%20repo%3Atldraw%2Ftldraw%20repo%3Aslidevjs%2Fslidev&per_page=100","stars":50107,"forks":3493,"license":"NOASSERTION"},"fetched_at":"2026-09-03T16:09:01.022Z"},{"source_type":"github","source_identifier":"tldraw/tldraw:readme:db3ce68f8c5f0652fe9724cfb5c64cb98898a64c4776e59e134c6e719296ea00","source_url":"https://raw.githubusercontent.com/tldraw/tldraw/main/README.md","raw_metadata":{"sha256":"db3ce68f8c5f0652fe9724cfb5c64cb98898a64c4776e59e134c6e719296ea00","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:37.417Z"}],"expected":null},{"identity":"repo:https://github.com/slidevjs/slidev","slug":"slidev-25a50641","name":"Slidev","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Viết nội dung bằng Markdown, biến nó thành slide có thể trình bày và ghi hình.","description":"Slidev tạo slide từ văn bản Markdown, thêm theme, sơ đồ, tương tác và chế độ thuyết trình. Tuy vốn hướng tới developer, nó cũng hữu ích cho creator làm tutorial hoặc workshop có người hỗ trợ thiết lập mẫu ban đầu.","long_description":"ĐIỂM NỔI BẬT\n• Markdown, theme và component tương tác.\n• Có annotation, presenter mode, sơ đồ Mermaid và ghi hình/camera.\n• Xuất PDF, PNG hoặc PPTX theo tính năng chính chủ.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nChuyển dàn ý hướng dẫn 5 bước thành slide rồi ghi bài giải thích để tái sử dụng trong video.\n\nBẮT ĐẦU\nThử bản online hoặc môi trường Node theo Getting Started; chọn theme trước khi nhập nội dung.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nCần quen Markdown và đôi khi code để tùy chỉnh. Tương tác web không luôn giữ nguyên khi xuất định dạng tĩnh; soát font Việt và tràn chữ.","canonical_url":"https://github.com/slidevjs/slidev","repository_url":"https://github.com/slidevjs/slidev","documentation_url":"https://raw.githubusercontent.com/slidevjs/slidev/main/README.md","owner_name":"slidevjs","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":78,"categories":["design","content","video"],"primaryCategory":"design","selectionReason":"Phù hợp Design & Frontend: Viết nội dung bằng Markdown, biến nó thành slide có thể trình bày và ghi hình. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Viết nội dung bằng Markdown, biến nó thành slide có thể trình bày và ghi hình.","highlights":["Markdown, theme và component tương tác.","Có annotation, presenter mode, sơ đồ Mermaid và ghi hình/camera.","Xuất PDF, PNG hoặc PPTX theo tính năng chính chủ."],"example":"Chuyển dàn ý hướng dẫn 5 bước thành slide rồi ghi bài giải thích để tái sử dụng trong video.","setup":"Thử bản online hoặc môi trường Node theo Getting Started; chọn theme trước khi nhập nội dung.","limitations":"Cần quen Markdown và đôi khi code để tùy chỉnh. Tương tác web không luôn giữ nguyên khi xuất định dạng tĩnh; soát font Việt và tràn chữ.","github":{"stars":48407,"forks":2170,"observedAt":"2026-09-03T16:09:01.022Z","url":"https://github.com/slidevjs/slidev","pushedAt":"2026-08-25T00:42:02Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/slidevjs/slidev/main/README.md","observedAt":"2026-09-03T16:10:39.271Z","sha256":"e1def8dcd916dc905b4a5f7d0ca7b10b6cc42a6d3664c6642e09d6933da80043"},"